package cryptosquare

import (
	"math"
	"strings"
	"unicode"
)

// Encode normalizes the plaintext (lower-casing, removing spaces and
// punctuation), lays the result out in a rectangle as square as possible,
// and reads it back down the columns, left to right, joining the columns
// with single spaces (padding short columns with trailing spaces).
func Encode(pt string) string {
	var s []rune
	for _, r := range pt {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			s = append(s, unicode.ToLower(r))
		}
	}

	n := len(s)
	if n == 0 {
		return ""
	}

	c := int(math.Ceil(math.Sqrt(float64(n))))
	r := (n + c - 1) / c

	chunks := make([]string, c)
	for j := 0; j < c; j++ {
		col := make([]rune, r)
		for i := 0; i < r; i++ {
			if idx := i*c + j; idx < n {
				col[i] = s[idx]
			} else {
				col[i] = ' '
			}
		}
		chunks[j] = string(col)
	}
	return strings.Join(chunks, " ")
}
